package io.temporal.workflow.activityTests;

import io.temporal.activity.ActivityOptions;
import io.temporal.client.WorkflowException;
import io.temporal.failure.ActivityFailure;
import io.temporal.failure.ApplicationFailure;
import io.temporal.testing.internal.SDKTestWorkflowRule;
import io.temporal.workflow.Workflow;
import io.temporal.workflow.shared.TestActivities.TestActivitiesImpl;
import io.temporal.workflow.shared.TestActivities.VariousTestActivities;
import io.temporal.workflow.shared.TestWorkflows.TestWorkflow1;
import java.time.Duration;
import org.junit.Assert;
import org.junit.Rule;
import org.junit.Test;

public class ActivityApplicationNoSpecifiedRetryTest {

  private final TestActivitiesImpl activitiesImpl = new TestActivitiesImpl();

  @Rule
  public SDKTestWorkflowRule testWorkflowRule =
      SDKTestWorkflowRule.newBuilder()
          .setWorkflowTypes(TestActivityApplicationNoSpecifiedRetry.class)
          .setActivityImplementations(activitiesImpl)
          .build();

  @Test
  public void testActivityApplicationNoSpecifiedRetry() {
    TestWorkflow1 workflowStub =
        testWorkflowRule.newWorkflowStubTimeoutOptions(TestWorkflow1.class);
    try {
      workflowStub.execute(testWorkflowRule.getTaskQueue());
      Assert.fail("unreachable");
    } catch (WorkflowException e) {
      Assert.assertTrue(e.getCause() instanceof ActivityFailure);
      Assert.assertTrue(e.getCause().getCause() instanceof ApplicationFailure);
      Assert.assertEquals(
          "simulatedType", ((ApplicationFailure) e.getCause().getCause()).getType());
    }

    // Since no retry policy is passed by the client, we fall back to the default retry policy of
    // the mock server, which mimics the default on a default Temporal deployment.
    Assert.assertEquals(3, activitiesImpl.applicationFailureCounter.get());
  }

  public static class TestActivityApplicationNoSpecifiedRetry implements TestWorkflow1 {

    private VariousTestActivities activities;

    @Override
    public String execute(String taskQueue) {
      ActivityOptions options =
          ActivityOptions.newBuilder()
              .setTaskQueue(taskQueue)
              .setScheduleToCloseTimeout(Duration.ofSeconds(200))
              .setStartToCloseTimeout(Duration.ofSeconds(1))
              .build();
      activities = Workflow.newActivityStub(VariousTestActivities.class, options);
      activities.throwApplicationFailureThreeTimes();
      return "ignored";
    }
  }
}

package io.temporal.authorization;

import static org.junit.Assert.*;

import io.grpc.*;
import io.temporal.client.ActivityClient;
import io.temporal.client.StartActivityOptions;
import io.temporal.client.WorkflowClient;
import io.temporal.client.WorkflowOptions;
import io.temporal.serviceclient.WorkflowServiceStubsOptions;
import io.temporal.testing.CloudTestExclusion.RequiresLocalServer;
import io.temporal.testing.CloudTestExclusionNote;
import io.temporal.testing.TestEnvironmentOptions;
import io.temporal.testing.TestWorkflowEnvironment;
import io.temporal.worker.Worker;
import io.temporal.workflow.Workflow;
import io.temporal.workflow.shared.TestWorkflows;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.experimental.categories.Category;
import org.junit.rules.TestWatcher;
import org.junit.runner.Description;

@CloudTestExclusionNote("This test directly creates and controls a local test service.")
@Category(RequiresLocalServer.class)
public class AuthorizationTokenTest {
  private static Metadata.Key<String> TEMPORAL_NAMESPACE_HEADER_KEY =
      Metadata.Key.of("temporal-namespace", Metadata.ASCII_STRING_MARSHALLER);
  private static final String TASK_QUEUE = "test-workflow";
  private static final String AUTH_TOKEN = "Bearer <token>";

  private TestWorkflowEnvironment testEnvironment;

  @Rule
  public TestWatcher watchman =
      new TestWatcher() {
        @Override
        protected void failed(Throwable e, Description description) {
          System.err.println(testEnvironment.getDiagnostics());
        }
      };

  private final List<GrpcRequest> loggedRequests = Collections.synchronizedList(new ArrayList<>());

  @Before
  public void setUp() {
    loggedRequests.clear();
    WorkflowServiceStubsOptions stubOptions =
        WorkflowServiceStubsOptions.newBuilder()
            .addGrpcClientInterceptor(
                new ClientInterceptor() {
                  @Override
                  public <ReqT, RespT> ClientCall<ReqT, RespT> interceptCall(
                      MethodDescriptor<ReqT, RespT> method, CallOptions callOptions, Channel next) {
                    return new LoggingClientCall<>(method, next.newCall(method, callOptions));
                  }

                  class LoggingClientCall<ReqT, RespT>
                      extends ForwardingClientCall.SimpleForwardingClientCall<ReqT, RespT> {

                    private final MethodDescriptor<ReqT, RespT> method;

                    LoggingClientCall(
                        MethodDescriptor<ReqT, RespT> method, ClientCall<ReqT, RespT> call) {
                      super(call);
                      this.method = method;
                    }

                    @Override
                    public void start(Listener<RespT> responseListener, Metadata headers) {
                      loggedRequests.add(
                          new GrpcRequest(
                              method.getBareMethodName(),
                              headers.get(
                                  AuthorizationGrpcMetadataProvider.AUTHORIZATION_HEADER_KEY),
                              headers.get(TEMPORAL_NAMESPACE_HEADER_KEY)));
                      super.start(responseListener, headers);
                    }
                  }
                })
            .addGrpcMetadataProvider(new AuthorizationGrpcMetadataProvider(() -> AUTH_TOKEN))
            .build();

    TestEnvironmentOptions options =
        TestEnvironmentOptions.newBuilder().setWorkflowServiceStubsOptions(stubOptions).build();

    testEnvironment = TestWorkflowEnvironment.newInstance(options);
  }

  @After
  public void tearDown() {
    testEnvironment.close();
  }

  @Test
  public void allRequestsShouldHaveAnAuthToken() {
    Worker worker = testEnvironment.newWorker(TASK_QUEUE);
    worker.registerWorkflowImplementationTypes(EmptyWorkflowImpl.class);
    testEnvironment.start();
    WorkflowClient client = testEnvironment.getWorkflowClient();
    WorkflowOptions options = WorkflowOptions.newBuilder().setTaskQueue(TASK_QUEUE).build();
    TestWorkflows.TestWorkflow1 workflow =
        client.newWorkflowStub(TestWorkflows.TestWorkflow1.class, options);
    String result = workflow.execute("input1");
    assertEquals("TestWorkflow1-input1", result);

    assertFalse(loggedRequests.isEmpty());
    // These methods are not namespace specific
    List<String> methodsToSkip =
        Arrays.asList("GetSystemInfo", "Check", "UnlockTimeSkipping", "LockTimeSkipping");
    for (GrpcRequest grpcRequest : loggedRequests) {
      assertEquals(
          "All requests should have an auth token", AUTH_TOKEN, grpcRequest.authTokenValue);
      if (!methodsToSkip.contains(grpcRequest.methodName)) {
        assertEquals(
            "All requests should have a namespace " + grpcRequest.methodName,
            testEnvironment.getNamespace(),
            grpcRequest.namespace);
      }
    }
  }

  @Test
  public void activityClientRequestsShouldHaveANamespace() {
    testEnvironment.start();
    ActivityClient client = testEnvironment.getActivityClient();
    StartActivityOptions options =
        StartActivityOptions.newBuilder()
            .setId("activity-id")
            .setTaskQueue(TASK_QUEUE)
            .setStartToCloseTimeout(Duration.ofMinutes(1))
            .build();

    // Only the outgoing request headers matter, not whether the server supports the call.
    try {
      client.start("SomeActivity", options);
    } catch (StatusRuntimeException ignored) {
    }

    List<GrpcRequest> startRequests =
        loggedRequests.stream()
            .filter(request -> request.methodName.equals("StartActivityExecution"))
            .collect(Collectors.toList());
    assertFalse("StartActivityExecution should have been called", startRequests.isEmpty());
    for (GrpcRequest grpcRequest : startRequests) {
      assertEquals(
          "StartActivityExecution should have an auth token",
          AUTH_TOKEN,
          grpcRequest.authTokenValue);
      assertEquals(
          "StartActivityExecution should have a namespace",
          testEnvironment.getNamespace(),
          grpcRequest.namespace);
    }
  }

  public static class EmptyWorkflowImpl implements TestWorkflows.TestWorkflow1 {

    @Override
    public String execute(String input) {
      Workflow.sleep(Duration.ofMinutes(5)); // test time skipping
      return Workflow.getInfo().getWorkflowType() + "-" + input;
    }
  }

  private static class GrpcRequest {
    final String methodName;
    final String authTokenValue;
    final String namespace;

    GrpcRequest(String methodName, String authTokenValue, String namespace) {
      this.methodName = methodName;
      this.authTokenValue = authTokenValue;
      this.namespace = namespace;
    }
  }
}

package io.temporal.spring.boot.autoconfigure;

import io.temporal.authorization.AuthorizationGrpcMetadataProvider;
import io.temporal.client.WorkflowClient;
import io.temporal.serviceclient.WorkflowServiceStubs;
import io.temporal.spring.boot.autoconfigure.properties.TemporalProperties;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.context.annotation.ComponentScan;
import org.springframework.context.annotation.FilterType;
import org.springframework.test.context.ActiveProfiles;

@SpringBootTest(classes = ApiKeyAuthTest.Configuration.class)
@ActiveProfiles(profiles = "api-key-auth")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
public class ApiKeyAuthTest {
  @Autowired ConfigurableApplicationContext applicationContext;

  @Autowired TemporalProperties temporalProperties;
  @Autowired WorkflowClient workflowClient;
  @Autowired WorkflowServiceStubs workflowServiceStubs;

  @BeforeEach
  void setUp() {
    applicationContext.start();
  }

  @Test
  public void testProperties() {
    Assertions.assertEquals("my-api-key", temporalProperties.getConnection().getApiKey());
    Assertions.assertEquals(1, workflowServiceStubs.getOptions().getGrpcMetadataProviders().size());
    Assertions.assertTrue(
        workflowServiceStubs.getOptions().getGrpcMetadataProviders().stream()
            .allMatch(
                provider ->
                    provider
                        .getMetadata()
                        .get(AuthorizationGrpcMetadataProvider.AUTHORIZATION_HEADER_KEY)
                        .equals("Bearer my-api-key")));
    Assertions.assertTrue(workflowServiceStubs.getOptions().getEnableHttps());
  }

  @ComponentScan(
      excludeFilters =
          @ComponentScan.Filter(
              pattern = "io\\.temporal\\.spring\\.boot\\.autoconfigure\\.byworkername\\..*",
              type = FilterType.REGEX))
  public static class Configuration {}
}

package io.temporal.worker;

import static io.temporal.testUtils.Eventually.assertEventually;
import static org.junit.Assert.*;
import static org.junit.Assume.assumeTrue;

import io.temporal.api.worker.v1.WorkerHeartbeat;
import io.temporal.api.workflowservice.v1.*;
import io.temporal.client.WorkflowClientOptions;
import io.temporal.common.WorkerDeploymentVersion;
import io.temporal.testing.internal.SDKTestWorkflowRule;
import java.time.Duration;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

public class WorkerHeartbeatDeploymentVersionTest {

  private static final Duration EVENTUALLY_TIMEOUT = Duration.ofSeconds(10);

  private static final String TEST_DEPLOYMENT_NAME = "test-deployment";
  private static final String TEST_BUILD_ID = "1.0.0";

  @Before
  public void checkServerSupportsHeartbeats() {
    assumeTrue(
        "Requires real server with worker heartbeat support",
        SDKTestWorkflowRule.useExternalService);
    assumeTrue(
        "Server does not support worker heartbeats",
        testWorkflowRule
            .getWorkflowClient()
            .getWorkflowServiceStubs()
            .blockingStub()
            .describeNamespace(
                DescribeNamespaceRequest.newBuilder()
                    .setNamespace(testWorkflowRule.getWorkflowClient().getOptions().getNamespace())
                    .build())
            .getNamespaceInfo()
            .getCapabilities()
            .getWorkerHeartbeats());
  }

  @Rule
  public SDKTestWorkflowRule testWorkflowRule =
      SDKTestWorkflowRule.newBuilder()
          .setTestTimeoutSeconds(15)
          .setWorkflowClientOptions(
              WorkflowClientOptions.newBuilder()
                  .setWorkerHeartbeatInterval(Duration.ofSeconds(1))
                  .build())
          .setWorkerOptions(
              WorkerOptions.newBuilder()
                  .setDeploymentOptions(
                      WorkerDeploymentOptions.newBuilder()
                          .setVersion(
                              new WorkerDeploymentVersion(TEST_DEPLOYMENT_NAME, TEST_BUILD_ID))
                          .build())
                  .build())
          .setDoNotStart(true)
          .build();

  @Test
  public void testDeploymentVersionInHeartbeat() throws Exception {
    testWorkflowRule.getTestEnvironment().start();

    String taskQueue = testWorkflowRule.getTaskQueue();

    // Discover the worker via ListWorkers, then verify deployment version via DescribeWorker
    assertEventually(
        EVENTUALLY_TIMEOUT,
        () -> {
          List<WorkerHeartbeat> workers = listWorkersForQueue(taskQueue);
          assertFalse("worker should appear via ListWorkers", workers.isEmpty());

          WorkerHeartbeat hb = describeWorker(workers.get(0).getWorkerInstanceKey());
          assertNotNull("DescribeWorker should return stored heartbeat", hb);
          assertTrue("deployment_version should be set", hb.hasDeploymentVersion());
          assertEquals(
              "deployment_version.deployment_name should match configured value",
              TEST_DEPLOYMENT_NAME,
              hb.getDeploymentVersion().getDeploymentName());
          assertEquals(
              "deployment_version.build_id should match configured value",
              TEST_BUILD_ID,
              hb.getDeploymentVersion().getBuildId());
        });
  }

  /**
   * Uses deprecated WorkersInfo field because the replacement is not yet populated by the server.
   */
  @SuppressWarnings("deprecation")
  private List<WorkerHeartbeat> listWorkersForQueue(String taskQueue) {
    try {
      ListWorkersResponse resp =
          testWorkflowRule
              .getWorkflowClient()
              .getWorkflowServiceStubs()
              .blockingStub()
              .listWorkers(
                  ListWorkersRequest.newBuilder()
                      .setNamespace(
                          testWorkflowRule.getWorkflowClient().getOptions().getNamespace())
                      .setQuery("TaskQueue = \"" + taskQueue + "\"")
                      .setPageSize(200)
                      .build());
      return resp.getWorkersInfoList().stream()
          .map(info -> info.getWorkerHeartbeat())
          .collect(Collectors.toList());
    } catch (io.grpc.StatusRuntimeException e) {
      if (e.getStatus().getCode() == io.grpc.Status.Code.RESOURCE_EXHAUSTED) {
        return java.util.Collections.emptyList();
      }
      throw e;
    }
  }

  private WorkerHeartbeat describeWorker(String workerInstanceKey) {
    try {
      DescribeWorkerResponse resp =
          testWorkflowRule
              .getWorkflowClient()
              .getWorkflowServiceStubs()
              .blockingStub()
              .describeWorker(
                  DescribeWorkerRequest.newBuilder()
                      .setNamespace(
                          testWorkflowRule.getWorkflowClient().getOptions().getNamespace())
                      .setWorkerInstanceKey(workerInstanceKey)
                      .build());
      return resp.getWorkerInfo().getWorkerHeartbeat();
    } catch (io.grpc.StatusRuntimeException e) {
      if (e.getStatus().getCode() == io.grpc.Status.Code.NOT_FOUND) {
        return null;
      }
      throw e;
    }
  }
}

package io.temporal.workflow.childWorkflowTests;

import io.temporal.testing.internal.SDKTestWorkflowRule;
import io.temporal.workflow.Async;
import io.temporal.workflow.ChildWorkflowOptions;
import io.temporal.workflow.ChildWorkflowStub;
import io.temporal.workflow.Workflow;
import io.temporal.workflow.shared.TestMultiArgWorkflowFunctions.TestMultiArgWorkflowImpl;
import io.temporal.workflow.shared.TestWorkflows.TestWorkflow1;
import org.junit.Assert;
import org.junit.Rule;
import org.junit.Test;

public class UntypedChildStubWorkflowAsyncInvokeTest {

  @Rule
  public SDKTestWorkflowRule testWorkflowRule =
      SDKTestWorkflowRule.newBuilder()
          .setWorkflowTypes(
              TestUntypedChildStubWorkflowAsyncInvoke.class, TestMultiArgWorkflowImpl.class)
          .build();

  @Test
  public void testUntypedChildStubWorkflowAsyncInvoke() {
    TestWorkflow1 client = testWorkflowRule.newWorkflowStub200sTimeoutOptions(TestWorkflow1.class);
    Assert.assertNull(client.execute(testWorkflowRule.getTaskQueue()));
  }

  public static class TestUntypedChildStubWorkflowAsyncInvoke implements TestWorkflow1 {

    @Override
    public String execute(String taskQueue) {
      ChildWorkflowOptions workflowOptions =
          ChildWorkflowOptions.newBuilder().setTaskQueue(taskQueue).build();
      ChildWorkflowStub stubF =
          Workflow.newUntypedChildWorkflowStub("TestNoArgsWorkflowFunc", workflowOptions);
      Assert.assertEquals("func", Async.function(stubF::<String>execute, String.class).get());
      // Workflow type overridden through the @WorkflowMethod.name
      ChildWorkflowStub stubF1 = Workflow.newUntypedChildWorkflowStub("func1", workflowOptions);
      Assert.assertEquals("1", Async.function(stubF1::<String>execute, String.class, "1").get());
      ChildWorkflowStub stubF2 =
          Workflow.newUntypedChildWorkflowStub("Test2ArgWorkflowFunc", workflowOptions);
      Assert.assertEquals(
          "12", Async.function(stubF2::<String>execute, String.class, "1", 2).get());
      ChildWorkflowStub stubF3 =
          Workflow.newUntypedChildWorkflowStub("Test3ArgWorkflowFunc", workflowOptions);
      Assert.assertEquals(
          "123", Async.function(stubF3::<String>execute, String.class, "1", 2, 3).get());
      ChildWorkflowStub stubF4 =
          Workflow.newUntypedChildWorkflowStub("Test4ArgWorkflowFunc", workflowOptions);
      Assert.assertEquals(
          "1234", Async.function(stubF4::<String>execute, String.class, "1", 2, 3, 4).get());
      ChildWorkflowStub stubF5 =
          Workflow.newUntypedChildWorkflowStub("Test5ArgWorkflowFunc", workflowOptions);
      Assert.assertEquals(
          "12345", Async.function(stubF5::<String>execute, String.class, "1", 2, 3, 4, 5).get());

      ChildWorkflowStub stubP =
          Workflow.newUntypedChildWorkflowStub("TestNoArgsWorkflowProc", workflowOptions);
      Async.procedure(stubP::<Void>execute, Void.class).get();
      ChildWorkflowStub stubP1 =
          Workflow.newUntypedChildWorkflowStub("Test1ArgWorkflowProc", workflowOptions);
      Async.procedure(stubP1::<Void>execute, Void.class, "1").get();
      ChildWorkflowStub stubP2 =
          Workflow.newUntypedChildWorkflowStub("Test2ArgWorkflowProc", workflowOptions);
      Async.procedure(stubP2::<Void>execute, Void.class, "1", 2).get();
      ChildWorkflowStub stubP3 =
          Workflow.newUntypedChildWorkflowStub("Test3ArgWorkflowProc", workflowOptions);
      Async.procedure(stubP3::<Void>execute, Void.class, "1", 2, 3).get();
      ChildWorkflowStub stubP4 =
          Workflow.newUntypedChildWorkflowStub("Test4ArgWorkflowProc", workflowOptions);
      Async.procedure(stubP4::<Void>execute, Void.class, "1", 2, 3, 4).get();
      ChildWorkflowStub stubP5 =
          Workflow.newUntypedChildWorkflowStub("Test5ArgWorkflowProc", workflowOptions);
      Async.procedure(stubP5::<Void>execute, Void.class, "1", 2, 3, 4, 5).get();
      return null;
    }
  }
}

package io.temporal.common.converter;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.protobuf.ByteString;
import io.temporal.api.common.v1.Payload;
import io.temporal.api.common.v1.Payloads;
import io.temporal.api.failure.v1.Failure;
import io.temporal.failure.ApplicationFailure;
import io.temporal.failure.TemporalFailure;
import io.temporal.internal.common.converter.TemporalTransferTypeDataConverter;
import io.temporal.payload.codec.PayloadCodec;
import io.temporal.payload.codec.PayloadCodecException;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.stream.Collectors;
import javax.annotation.Nonnull;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.Timeout;

public class CodecDataConverterTest {
  public @Rule Timeout timeout = Timeout.seconds(10);

  private CodecDataConverter dataConverter;

  @Before
  public void setUp() {
    PrefixPayloadCodec prefixPayloadCodec = new PrefixPayloadCodec();
    this.dataConverter =
        new CodecDataConverter(
            DefaultDataConverter.newDefaultInstance(),
            Collections.singletonList(prefixPayloadCodec),
            true);
  }

  @Test
  public void testMessageAndStackTraceAreCorrectlyEncoded() {
    try {
      ApplicationFailure causeException =
          ApplicationFailure.newFailure("CauseException", "CauseExceptionType");
      throw ApplicationFailure.newFailureWithCause("Message", "Type", causeException);
    } catch (ApplicationFailure originalException) {
      Failure failure = dataConverter.exceptionToFailure(originalException);

      // Assert the failure's message and stack trace were correctly moved to encoded attributes
      assertEquals("Encoded failure", failure.getMessage());
      assertEquals("", failure.getStackTrace());
      assertTrue(failure.hasEncodedAttributes());

      // Assert this was also done on the cause
      assertEquals("Encoded failure", failure.getCause().getMessage());
      assertEquals("", failure.getCause().getStackTrace());
      assertTrue(failure.getCause().hasEncodedAttributes());

      // Assert encoded_attributes were actually encoded
      assertTrue(isEncoded(failure.getEncodedAttributes()));
      assertTrue(isEncoded(failure.getCause().getEncodedAttributes()));
    }
  }

  @Test
  public void testMessageAndStackTraceAreCorrectlyDecoded() {
    try {
      ApplicationFailure causeException =
          ApplicationFailure.newFailure("CauseException", "CauseExceptionType");
      throw ApplicationFailure.newFailureWithCause("Message", "Type", causeException);
    } catch (ApplicationFailure originalException) {
      Failure failure = dataConverter.exceptionToFailure(originalException);
      TemporalFailure decodedException =
          (TemporalFailure) dataConverter.failureToException(failure);

      assertEquals("Message", decodedException.getOriginalMessage());
      assertEquals(
          "CauseException", ((TemporalFailure) decodedException.getCause()).getOriginalMessage());

      assertEquals(
          originalException.getStackTrace()[0].toString(),
          decodedException.getStackTrace()[0].toString());
      assertEquals(
          originalException.getCause().getStackTrace()[0].toString(),
          decodedException.getCause().getStackTrace()[0].toString());
    }
  }

  @Test
  public void testDetailsAreEncoded() {
    Object[] details = new Object[] {"test", 123, new int[] {1, 2, 3}};

    ApplicationFailure originalException =
        ApplicationFailure.newFailure("Message", "Type", details);
    Failure failure = dataConverter.exceptionToFailure(originalException);
    Exception decodedException = dataConverter.failureToException(failure);

    // Assert details were actually encoded
    List<Payload> encodedDetailsPayloads =
        failure.getApplicationFailureInfo().getDetails().getPayloadsList();
    assertTrue(isEncoded(encodedDetailsPayloads.get(0)));
    assertTrue(isEncoded(encodedDetailsPayloads.get(1)));
    assertTrue(isEncoded(encodedDetailsPayloads.get(2)));

    // Assert details can be decoded
    Values decodedDetailsPayloads = ((ApplicationFailure) decodedException).getDetails();
    assertEquals("test", decodedDetailsPayloads.get(0, String.class, String.class));
    assertEquals((Integer) 123, decodedDetailsPayloads.get(1, Integer.class, Integer.class));
    assertArrayEquals(new int[] {1, 2, 3}, decodedDetailsPayloads.get(2, int[].class, int[].class));
  }

  @Test
  public void transferTypeFailureDetailsAreEncodedOnce() {
    DataConverter transferAware = TemporalTransferTypeDataConverter.wrap(dataConverter);
    Failure failure =
        transferAware.exceptionToFailure(
            ApplicationFailure.newFailure("Message", "Type", new TransferTypeTestModel("detail")));

    Payload detail = failure.getApplicationFailureInfo().getDetails().getPayloads(0);
    assertTrue(isEncoded(detail));
    ApplicationFailure restored = (ApplicationFailure) transferAware.failureToException(failure);
    TransferTypeTestModel model = restored.getDetails().get(0, TransferTypeTestModel.class);
    assertEquals("detail", model.value());
    assertTrue(model.wasTransferred());
    assertEquals("Message", restored.getOriginalMessage());
  }

  @Test
  public void testRawValuePassThrough() {
    Payload p = Payload.newBuilder().setData(ByteString.copyFromUtf8("test")).build();
    Optional<Payloads> data = dataConverter.toPayloads(new RawValue(p));
    // Assert that the payload is still encoded
    assertTrue(isEncoded(data.get().getPayloads(0)));
    RawValue converted = dataConverter.fromPayloads(0, data, RawValue.class, RawValue.class);
    assertEquals(p, converted.getPayload());
  }

  static boolean isEncoded(Payload payload) {
    return payload.getData().startsWith(PrefixPayloadCodec.PREFIX);
  }

  public static final class PrefixPayloadCodec implements PayloadCodec {
    public static final ByteString PREFIX = ByteString.copyFromUtf8("ENCODED: ");

    @Override
    @Nonnull
    public List<Payload> encode(@Nonnull List<Payload> payloads) {
      return payloads.stream().map(this::encode).collect(Collectors.toList());
    }

    private Payload encode(Payload decodedPayload) {
      ByteString encodedData = PREFIX.concat(decodedPayload.getData());
      return decodedPayload.toBuilder().setData(encodedData).build();
    }

    @Override
    @Nonnull
    public List<Payload> decode(@Nonnull List<Payload> payloads) {
      return payloads.stream().map(this::decode).collect(Collectors.toList());
    }

    private Payload decode(Payload encodedPayload) {
      ByteString encodedData = encodedPayload.getData();
      if (!encodedData.startsWith(PREFIX))
        throw new PayloadCodecException("Payload is not correctly encoded");
      ByteString decodedData = encodedData.substring(PREFIX.size());
      return encodedPayload.toBuilder().setData(decodedData).build();
    }
  }
}

package io.temporal.internal.worker;

import static org.junit.Assert.assertEquals;

import com.uber.m3.tally.RootScopeBuilder;
import com.uber.m3.tally.Scope;
import com.uber.m3.util.ImmutableMap;
import io.grpc.*;
