import io.temporal.workflow.Workflow;
import io.temporal.workflow.shared.TestActivities;
import io.temporal.workflow.shared.TestWorkflows;
import java.time.Duration;
import java.util.Collections;
import java.util.Map;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

public class WorkflowSlotGrpcInterceptedTests {
  private final int MAX_CONCURRENT_WORKFLOW_TASK_EXECUTION_SIZE = 100;
  private final int MAX_CONCURRENT_ACTIVITY_EXECUTION_SIZE = 1000;
  private final int MAX_CONCURRENT_LOCAL_ACTIVITY_EXECUTION_SIZE = 10000;
  private final int MAX_CONCURRENT_NEXUS_EXECUTION_SIZE = 10000;
  private final CountingSlotSupplier<WorkflowSlotInfo> workflowTaskSlotSupplier =
      new CountingSlotSupplier<>(MAX_CONCURRENT_WORKFLOW_TASK_EXECUTION_SIZE);
  private final CountingSlotSupplier<ActivitySlotInfo> activityTaskSlotSupplier =
      new CountingSlotSupplier<>(MAX_CONCURRENT_ACTIVITY_EXECUTION_SIZE);
  private final CountingSlotSupplier<LocalActivitySlotInfo> localActivitySlotSupplier =
      new CountingSlotSupplier<>(MAX_CONCURRENT_LOCAL_ACTIVITY_EXECUTION_SIZE);
  private final CountingSlotSupplier<NexusSlotInfo> nexusSlotSupplier =
      new CountingSlotSupplier<>(MAX_CONCURRENT_NEXUS_EXECUTION_SIZE);
  private final TestStatsReporter reporter = new TestStatsReporter();
  private static final MaybeFailWFTResponseInterceptor MAYBE_FAIL_INTERCEPTOR =
      new MaybeFailWFTResponseInterceptor();
  Scope metricsScope =
      new RootScopeBuilder().reporter(reporter).reportEvery(com.uber.m3.util.Duration.ofMillis(1));

  @Rule
  public SDKTestWorkflowRule testWorkflowRule =
      SDKTestWorkflowRule.newBuilder()
          .setWorkflowServiceStubsOptions(
              WorkflowServiceStubsOptions.newBuilder()
                  .setGrpcClientInterceptors(Collections.singletonList(MAYBE_FAIL_INTERCEPTOR))
                  .build())
          .setWorkerOptions(
              WorkerOptions.newBuilder()
                  .setWorkerTuner(
                      new CompositeTuner(
                          workflowTaskSlotSupplier,
                          activityTaskSlotSupplier,
                          localActivitySlotSupplier,
                          nexusSlotSupplier))
                  .build())
          .setMetricsScope(metricsScope)
          .setActivityImplementations(new TestActivities.TestActivitiesImpl())
          .setWorkflowTypes(UnblockableWorkflow.class)
          .setDoNotStart(true)
          .build();

  @Before
  public void setup() {
    reporter.flush();
    MAYBE_FAIL_INTERCEPTOR.reset();
  }

  @After
  public void tearDown() {
    testWorkflowRule.getTestEnvironment().close();
    assertEquals(
        workflowTaskSlotSupplier.reservedCount.get(), workflowTaskSlotSupplier.releasedCount.get());
    assertEquals(
        activityTaskSlotSupplier.reservedCount.get(), activityTaskSlotSupplier.releasedCount.get());
    assertEquals(
        localActivitySlotSupplier.reservedCount.get(),
        localActivitySlotSupplier.releasedCount.get());
  }

  public static class UnblockableWorkflow implements TestWorkflows.TestSignaledWorkflow {
    private boolean unblocked = false;

    private final TestActivities.VariousTestActivities activities =
        Workflow.newActivityStub(
            TestActivities.VariousTestActivities.class,
            ActivityOptions.newBuilder()
                .setStartToCloseTimeout(Duration.ofSeconds(10))
                // If the task comes eagerly, since the interceptor blows us up we drop it
                // and that can cause timeouts.
                .setDisableEagerExecution(true)
                .setRetryOptions(RetryOptions.newBuilder().setMaximumAttempts(1).build())
                .validateAndBuildWithDefaults());

    @Override
    public String execute() {
      Workflow.await(() -> unblocked);
      activities.activity();
      return "";
    }

    @Override
    public void signal(String arg) {
      unblocked = true;
    }
  }

  @Test
  public void TestWFTResponseFailsThenWorks() {
    testWorkflowRule.getTestEnvironment().start();
    WorkflowClient client = testWorkflowRule.getWorkflowClient();
    TestWorkflows.TestSignaledWorkflow workflow =
        client.newWorkflowStub(
            TestWorkflows.TestSignaledWorkflow.class,
            WorkflowOptions.newBuilder()
                .setTaskQueue(testWorkflowRule.getTaskQueue())
                // If the task comes eagerly, since the interceptor blows us up we drop it
                // and that can cause timeouts.
                .setDisableEagerExecution(true)
                .validateBuildWithDefaults());
    WorkflowClient.start(workflow::execute);
    workflow.signal("whatever");
    workflow.execute();
    // All slots should be available
    assertAllSlotsAvailable();
  }

  @Test
  public void TestActivityResponseFailsThenWorks() {
    MAYBE_FAIL_INTERCEPTOR.failActivity = true;
    testWorkflowRule.getTestEnvironment().start();
    WorkflowClient client = testWorkflowRule.getWorkflowClient();
    TestWorkflows.TestSignaledWorkflow workflow =
        client.newWorkflowStub(
            TestWorkflows.TestSignaledWorkflow.class,
            WorkflowOptions.newBuilder()
                .setTaskQueue(testWorkflowRule.getTaskQueue())
                .validateBuildWithDefaults());
    WorkflowClient.start(workflow::execute);
    workflow.signal("whatever");
    workflow.execute();
    // All slots should be available
    assertAllSlotsAvailable();
  }

  private void assertAllSlotsAvailable() {
    try {
      // There can be a delay in metrics emission, another option if this
      // is too flaky is to poll the metrics.
      Thread.sleep(100);
    } catch (InterruptedException e) {
      throw new RuntimeException(e);
    }
    reporter.assertGauge(
        MetricsType.WORKER_TASK_SLOTS_AVAILABLE,
        getWorkerTags("WorkflowWorker"),
        MAX_CONCURRENT_WORKFLOW_TASK_EXECUTION_SIZE);
    reporter.assertGauge(
        MetricsType.WORKER_TASK_SLOTS_AVAILABLE,
        getWorkerTags("ActivityWorker"),
        MAX_CONCURRENT_ACTIVITY_EXECUTION_SIZE);
    reporter.assertGauge(
        MetricsType.WORKER_TASK_SLOTS_AVAILABLE,
        getWorkerTags("LocalActivityWorker"),
        MAX_CONCURRENT_LOCAL_ACTIVITY_EXECUTION_SIZE);
    reporter.assertGauge(MetricsType.WORKER_TASK_SLOTS_USED, getWorkerTags("WorkflowWorker"), 0);
    reporter.assertGauge(MetricsType.WORKER_TASK_SLOTS_USED, getWorkerTags("ActivityWorker"), 0);
    reporter.assertGauge(
        MetricsType.WORKER_TASK_SLOTS_USED, getWorkerTags("LocalActivityWorker"), 0);
  }

  private Map<String, String> getWorkerTags(String workerType) {
    return ImmutableMap.of(
        "worker_type",
        workerType,
        "task_queue",
        testWorkflowRule.getTaskQueue(),
        "namespace",
        testWorkflowRule.getWorkflowClient().getOptions().getNamespace());
  }

  private static class MaybeFailWFTResponseInterceptor implements ClientInterceptor {
    boolean didFailOnce = false;
    boolean failActivity;

    @Override
    public <ReqT, RespT> ClientCall<ReqT, RespT> interceptCall(
        MethodDescriptor<ReqT, RespT> method, CallOptions callOptions, Channel next) {
      if (!failActivity && method == WorkflowServiceGrpc.getRespondWorkflowTaskCompletedMethod()) {
        return new MaybeFailWFTResponseInterceptor.FailResponseCall<>(
            next.newCall(method, callOptions));
      } else if (failActivity
          && method == WorkflowServiceGrpc.getRespondActivityTaskCompletedMethod()) {
        return new MaybeFailWFTResponseInterceptor.FailResponseCall<>(
            next.newCall(method, callOptions));
      }
      return next.newCall(method, callOptions);
    }

    public void reset() {
      didFailOnce = false;
      failActivity = false;
    }

    private final class FailResponseCall<ReqT, RespT>
        extends ForwardingClientCall.SimpleForwardingClientCall<ReqT, RespT> {

      FailResponseCall(ClientCall<ReqT, RespT> call) {
        super(call);
      }

      @Override
      public void start(Listener<RespT> responseListener, Metadata headers) {

        responseListener =
            new ForwardingClientCallListener.SimpleForwardingClientCallListener<RespT>(
                responseListener) {
              @Override
              public void onMessage(RespT message) {
                if (!didFailOnce) {
                  didFailOnce = true;
                  // Throw some non-retryable error code
                  throw new StatusRuntimeException(Status.UNAUTHENTICATED);
                }
                super.onMessage(message);
              }
            };
        super.start(responseListener, headers);
      }
    }
  }
}

package io.temporal.client.schedules;

import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import io.temporal.common.interceptors.ScheduleClientCallsInterceptor;
import io.temporal.common.interceptors.ScheduleClientCallsInterceptorBase;
import io.temporal.common.interceptors.ScheduleClientInterceptor;
import io.temporal.testing.internal.TracingWorkerInterceptor;
import io.temporal.workflow.unsafe.WorkflowUnsafe;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * A ScheduleClientInterceptor that just logs the calls it intercepts. The implementation is taken
 * from TracingWorkerInterceptor, with very minor tweaks.
 */
public class TracingScheduleInterceptor implements ScheduleClientInterceptor {
  private static final Logger log = LoggerFactory.getLogger(TracingWorkerInterceptor.class);

  private final FilteredTrace trace;
  private List<String> expected;

  public TracingScheduleInterceptor(FilteredTrace trace) {
    this.trace = trace;
  }

  public String getTrace() {
    return String.join("\n", trace.getImpl());
  }

  public void setExpected(String... expected) {
    this.expected = Arrays.asList(expected);
  }

  public void assertExpected() {
    if (expected != null) {
      List<String> traceElements = trace.getImpl();
      if (traceElements.isEmpty()) {
        fail("Expected to find traces, but found none");
      }

      for (int i = 0; i < traceElements.size(); i++) {
        String t = traceElements.get(i);
        String expectedRegExp;
        if (expected.size() <= i) {
          expectedRegExp = "";
        } else {
          expectedRegExp = expected.get(i);
        }
        assertTrue(
            t
                + " doesn't match "
                + expectedRegExp
                + ": \n expected=\n"
                + String.join("\n", expected)
                + "\n actual=\n"
                + String.join("\n", traceElements)
                + "\n",
            t.matches(expectedRegExp));
      }
    }
  }

  @Override
  public ScheduleClientCallsInterceptor scheduleClientCallsInterceptor(
      ScheduleClientCallsInterceptor next) {
    return new TracingScheduleCallsInterceptor(trace, next);
  }

  public static class TracingScheduleCallsInterceptor extends ScheduleClientCallsInterceptorBase {
    private final FilteredTrace trace;
    private final ScheduleClientCallsInterceptor next;

    public TracingScheduleCallsInterceptor(
        FilteredTrace trace, ScheduleClientCallsInterceptor next) {
      super(next);
      this.trace = trace;
      this.next = next;
    }

    @Override
    public void createSchedule(CreateScheduleInput input) {
      trace.add("createSchedule: " + input.getId());
      next.createSchedule(input);
    }

    @Override
    public ListScheduleOutput listSchedules(ListSchedulesInput input) {
      trace.add("listSchedules");
      return next.listSchedules(input);
    }

    @Override
    public void backfillSchedule(BackfillScheduleInput input) {
      trace.add("backfillSchedule: " + input.getScheduleId());
      next.backfillSchedule(input);
    }

    @Override
    public void deleteSchedule(DeleteScheduleInput input) {
      trace.add("deleteSchedule: " + input.getScheduleId());
      next.deleteSchedule(input);
    }

    @Override
    public DescribeScheduleOutput describeSchedule(DescribeScheduleInput input) {
      trace.add("describeSchedule: " + input.getScheduleId());
      return next.describeSchedule(input);
    }

    @Override
    public void pauseSchedule(PauseScheduleInput input) {
      trace.add("pauseSchedule: " + input.getScheduleId());
      next.pauseSchedule(input);
    }

    @Override
    public void triggerSchedule(TriggerScheduleInput input) {
      trace.add("triggerSchedule: " + input.getScheduleId());
      next.triggerSchedule(input);
    }

    @Override
    public void unpauseSchedule(UnpauseScheduleInput input) {
      trace.add("unpauseSchedule: " + input.getScheduleId());
      next.unpauseSchedule(input);
    }

    @Override
    public void updateSchedule(UpdateScheduleInput input) {
      trace.add("updateSchedule: " + input.getDescription().getId());
      next.updateSchedule(input);
    }
  }

  public static class FilteredTrace {

    private final List<String> impl = Collections.synchronizedList(new ArrayList<>());

    public boolean add(String s) {
      log.trace("FilteredTrace isReplaying=" + WorkflowUnsafe.isReplaying());
      if (!WorkflowUnsafe.isReplaying()) {
        return impl.add(s);
      }
      return true;
    }

    List<String> getImpl() {
      return impl;
    }
  }
}

