    @Override
    public Duration execute(boolean useLocalActivity) {
      long t1 = Workflow.currentTimeMillis();
      if (useLocalActivity) {
        localActivities.execute();
      } else {
        activities.execute();
      }
      long t2 = Workflow.currentTimeMillis();
      return Duration.ofMillis(t2 - t1);
    }
  }

  public static class NextRetryDelayActivityImpl implements TestActivities.NoArgsActivity {
    private final AtomicInteger attemptCount = new AtomicInteger();

    @Override
    public void execute() {
      attemptCount.incrementAndGet();
      int attempt = Activity.getExecutionContext().getInfo().getAttempt();
      if (attempt < 4) {
        throw ApplicationFailure.newFailureWithCauseAndDelay(
            "test retry delay failure " + attempt,
            "test failure",
            null,
            Duration.ofSeconds(attempt));
      }
    }

    public int getAttemptCount() {
      return attemptCount.get();
    }
  }
}

package io.temporal.workflow;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import io.temporal.activity.ActivityOptions;
import io.temporal.client.WorkflowClient;
import io.temporal.client.WorkflowException;
import io.temporal.client.WorkflowOptions;
import io.temporal.common.RetryOptions;
import io.temporal.failure.ApplicationFailure;
import io.temporal.failure.TerminatedFailure;
import io.temporal.testing.internal.SDKTestWorkflowRule;
import io.temporal.workflow.shared.TestActivities.TestActivity1;
import io.temporal.workflow.shared.TestWorkflows.TestWorkflow1;
import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Rule;
import org.junit.Test;

public class WorkflowRetryAfterActivityFailureTest {

  private static AtomicInteger failureCounter = new AtomicInteger(1);

  @Rule
  public SDKTestWorkflowRule testWorkflowRule =
      SDKTestWorkflowRule.newBuilder()
          .setWorkflowTypes(WorkflowImpl.class)
          .setActivityImplementations(new FailingActivityImpl())
          .build();

  @Test
  public void testWorkflowRetryAfterActivityFailure() {
    WorkflowClient client = testWorkflowRule.getWorkflowClient();
    TestWorkflow1 workflow =
        client.newWorkflowStub(
            TestWorkflow1.class,
            WorkflowOptions.newBuilder()
                .setTaskQueue(testWorkflowRule.getTaskQueue())
                // Retry the workflow though
                .setRetryOptions(RetryOptions.newBuilder().setMaximumAttempts(2).build())
                .validateBuildWithDefaults());

    // Retry once
    assertEquals("bar", workflow.execute("input"));
    assertEquals(-1, failureCounter.get());

    // Non retryable failure
    try {
      failureCounter = new AtomicInteger(1);
      workflow.execute("terminated");
    } catch (WorkflowException e) {
      assertTrue(e.getCause() instanceof TerminatedFailure);
      assertEquals(0, failureCounter.get());
    }
  }

  public static class WorkflowImpl implements TestWorkflow1 {
    private final TestActivity1 activity =
        Workflow.newActivityStub(
            TestActivity1.class,
            ActivityOptions.newBuilder()
                .setStartToCloseTimeout(Duration.ofSeconds(1))
                // Don't retry the activity
                .setRetryOptions(RetryOptions.newBuilder().setMaximumAttempts(1).build())
                .validateAndBuildWithDefaults());

    @Override
    public String execute(String input) {
      if (input.equals("terminated") && failureCounter.getAndDecrement() > 0) {
        throw new TerminatedFailure(input, null);
      }
      return activity.execute(input);
    }
  }

  public static class FailingActivityImpl implements TestActivity1 {
    @Override
    public String execute(String input) {
      if (failureCounter.getAndDecrement() > 0) {
        if (input.equals("terminated")) {
          throw new TerminatedFailure(input, null);
        } else {
          throw ApplicationFailure.newFailure("fail", "fail");
        }
      } else {
        return "bar";
      }
    }
  }
}

package io.temporal.workflow;

import static org.junit.Assert.*;

import com.google.common.base.Throwables;
import io.grpc.Context;
import io.grpc.Status;
import io.grpc.StatusRuntimeException;
import io.temporal.client.WorkflowServiceException;
import io.temporal.testing.internal.SDKTestWorkflowRule;
import io.temporal.workflow.shared.TestWorkflows.NoArgsWorkflow;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.AfterClass;
import org.junit.BeforeClass;
import org.junit.Rule;
import org.junit.Test;

public class GrpcRetryerFunctionalTest {

  @Rule
  public SDKTestWorkflowRule testWorkflowRule =
      SDKTestWorkflowRule.newBuilder().setWorkflowTypes(FiveSecondsSleepingWorkflow.class).build();

  private static ScheduledExecutorService scheduledExecutor;

  @BeforeClass
  public static void beforeClass() {
    scheduledExecutor = Executors.newScheduledThreadPool(1);
  }

  @AfterClass
  public static void afterClass() throws Exception {
    scheduledExecutor.shutdownNow();
  }

  /**
   * This test verifies that if GRPC Deadline in GRPC Context is reached even before the request, we
   * return fast and with the correct DEADLINE_EXCEEDED error, and we don't try to retry the
   * DEADLINE_EXCEEDED.
   */
  @Test(timeout = 2000)
  public void contextDeadlineExpiredAtStart() {
    NoArgsWorkflow workflow = testWorkflowRule.newWorkflowStub(NoArgsWorkflow.class);

    AtomicReference<Exception> exRef = new AtomicReference<>();
    Context.current()
        .withDeadlineAfter(-1, TimeUnit.MILLISECONDS, scheduledExecutor)
        // create a new deadline that already expired
        .run(
            () -> {
              try {
                workflow.execute();
                fail();
              } catch (Exception e) {
                exRef.set(e);
              }
            });

    WorkflowServiceException exception = (WorkflowServiceException) exRef.get();
    Throwable cause = exception.getCause();

    assertTrue(cause instanceof StatusRuntimeException);
    assertEquals(
        Status.DEADLINE_EXCEEDED.getCode(), ((StatusRuntimeException) cause).getStatus().getCode());
  }

  /**
   * This test verifies that if GRPC Deadline reached in the middle of workflow execution, we return
   * fast and with the correct DEADLINE_EXCEEDED error, and we don't try to retry the
   * DEADLINE_EXCEEDED.
   */
  @Test(timeout = 2500)
  public void contextDeadlineExpiredBeforeWorkflowFinish() {
    NoArgsWorkflow workflow = testWorkflowRule.newWorkflowStub(NoArgsWorkflow.class);

    AtomicReference<Exception> exRef = new AtomicReference<>();
    Context.current()
        .withDeadlineAfter(500, TimeUnit.MILLISECONDS, scheduledExecutor)
        // create a deadline that expires before workflow finishes
        .run(
            () -> {
              try {
                workflow.execute();
                fail();
              } catch (Exception e) {
                exRef.set(e);
              }
            });

    Exception exception = exRef.get();
    assertTrue(
        "Expected WorkflowServiceException, got "
            + exception
            + " \n "
            + Throwables.getStackTraceAsString(exception),
        exception instanceof WorkflowServiceException);
    Throwable cause = exception.getCause();

    assertTrue(cause instanceof StatusRuntimeException);
    assertEquals(
        Status.DEADLINE_EXCEEDED.getCode(), ((StatusRuntimeException) cause).getStatus().getCode());
  }

  public static class FiveSecondsSleepingWorkflow implements NoArgsWorkflow {

    @Override
    public void execute() {
      try {
        Thread.sleep(5000);
      } catch (InterruptedException ignored) {
        Thread.currentThread().interrupt();
      }
    }
  }
}

